import React from 'react';
import MuiDialogContent, { DialogContentProps } from '@mui/material/DialogContent';
import PlaceholderArea from '../utils/PlaceholderArea';

const PopperContent = ({ ...props }: DialogContentProps) => {
  const { children, ...rest } = props;

  return (
    <MuiDialogContent
      {...rest}
    >
      {children || <PlaceholderArea height="200px" width="350px" />}
    </MuiDialogContent>
  );
};

PopperContent.defaultProps = {
};

export * from '@mui/material/DialogContent';
export default PopperContent;
